param(
  [Parameter(Mandatory = $false)]
  [string]$RepoRoot = "."
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest
$Utf8NoBom = New-Object System.Text.UTF8Encoding -ArgumentList $false

function Fail([string]$Message) {
  throw $Message
}

function Decode-B64([string]$Value) {
  return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value))
}

function Resolve-RepoPath([string]$RelativePath) {
  return Join-Path $script:ResolvedRepo $RelativePath
}

function Read-TextLf([string]$RelativePath) {
  $path = Resolve-RepoPath $RelativePath
  if (-not (Test-Path -LiteralPath $path)) {
    Fail "No existe el archivo esperado: $RelativePath"
  }

  $text = [System.IO.File]::ReadAllText($path)
  return $text.Replace("`r`n", "`n").Replace("`r", "`n")
}

function Write-TextLf([string]$RelativePath, [string]$Content) {
  $path = Resolve-RepoPath $RelativePath
  $directory = Split-Path -Parent $path
  if (-not (Test-Path -LiteralPath $directory)) {
    New-Item -ItemType Directory -Path $directory -Force | Out-Null
  }

  $normalized = $Content.Replace("`r`n", "`n").Replace("`r", "`n")
  [System.IO.File]::WriteAllText($path, $normalized, $script:Utf8NoBom)
}

function Assert-ExactB64(
  [string]$RelativePath,
  [string]$OldB64,
  [string]$Description
) {
  $text = Read-TextLf $RelativePath
  $old = Decode-B64 $OldB64
  $index = $text.IndexOf($old, [System.StringComparison]::Ordinal)

  if ($index -lt 0) {
    Fail "Preflight: no se encontro el bloque esperado para: $Description ($RelativePath)"
  }

  $second = $text.IndexOf($old, $index + $old.Length, [System.StringComparison]::Ordinal)
  if ($second -ge 0) {
    Fail "Preflight: el bloque para '$Description' aparece mas de una vez en $RelativePath."
  }
}

function Assert-LastReturn([string]$RelativePath, [string]$Description) {
  $text = Read-TextLf $RelativePath
  $start = $text.LastIndexOf("  return (`n", [System.StringComparison]::Ordinal)
  $end = $text.LastIndexOf("`n}", [System.StringComparison]::Ordinal)

  if ($start -lt 0 -or $end -le $start) {
    Fail "Preflight: no se pudo localizar el return final para: $Description ($RelativePath)"
  }
}

function Write-B64File([string]$RelativePath, [string]$ContentB64, [string]$Description) {
  Write-TextLf $RelativePath (Decode-B64 $ContentB64)
  Write-Host "OK: $Description"
}

function Replace-ExactB64(
  [string]$RelativePath,
  [string]$OldB64,
  [string]$NewB64,
  [string]$Description
) {
  $text = Read-TextLf $RelativePath
  $old = Decode-B64 $OldB64
  $new = Decode-B64 $NewB64
  $index = $text.IndexOf($old, [System.StringComparison]::Ordinal)

  if ($index -lt 0) {
    Fail "No se encontro el bloque esperado para: $Description ($RelativePath)"
  }

  $second = $text.IndexOf($old, $index + $old.Length, [System.StringComparison]::Ordinal)
  if ($second -ge 0) {
    Fail "El bloque para '$Description' aparece mas de una vez en $RelativePath."
  }

  $updated = $text.Substring(0, $index) + $new + $text.Substring($index + $old.Length)
  Write-TextLf $RelativePath $updated
  Write-Host "OK: $Description"
}

function Replace-LastReturnB64(
  [string]$RelativePath,
  [string]$ReplacementB64,
  [string]$Description
) {
  $text = Read-TextLf $RelativePath
  $start = $text.LastIndexOf("  return (`n", [System.StringComparison]::Ordinal)
  $end = $text.LastIndexOf("`n}", [System.StringComparison]::Ordinal)

  if ($start -lt 0 -or $end -le $start) {
    Fail "No se pudo localizar el return final para: $Description ($RelativePath)"
  }

  $replacement = Decode-B64 $ReplacementB64
  $updated = $text.Substring(0, $start) + $replacement + $text.Substring($end)
  Write-TextLf $RelativePath $updated
  Write-Host "OK: $Description"
}

